// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadMontserrat = makeLoadFont('Montserrat');

const { fontFamily: montserratFamily } = loadMontserrat();



export type ChecklistProps = Record<string, any>;

const ChecklistAnimation: React.FC<ChecklistProps> = ({
  backgroundColor = "#050014",
  transparentBackground = false,
  durationInSeconds = 10,
  cardColor = "#0055FF",
  glowColor = "#00FFFF",
  accentColor = "#FFEE00",
  checkColor = "#00FF44",
  items = [
    "SURVIVE 100 DAYS",
    "BEAT THE LASER MAZE",
    "EAT ONLY SPICY FOOD",
    "FIND THE GOLDEN TICKET",
    "WIN $1,000,000!",
  ],
  staggerFrames = 25,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Global animations
  const cardEntrance = spring({
    frame,
    fps,
    config: { damping: 12, stiffness: 100 }, // More aggressive bounce
  });

  // Snappier scale for a "POW" entrance
  const cardScale = interpolate(cardEntrance, [0, 1], [0.5, 1]);
  const cardOpacity = interpolate(cardEntrance, [0, 1], [0, 1]);

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        justifyContent: "center",
        alignItems: "center",
        fontFamily: montserratFamily,
        overflow: "hidden",
      }}
    >
      {/* Animated Sunburst Background */}
      {!transparentBackground && (
        <div
          style={{
            position: "absolute",
            top: "-50%",
            left: "-50%",
            width: "200%",
            height: "200%",
            background: `repeating-conic-gradient(from 0deg, rgba(255,255,255,0.05) 0deg 15deg, transparent 15deg 30deg)`,
            transform: `rotate(${frame * 0.2}deg)`,
            pointerEvents: "none",
          }}
        />
      )}

      {/* Main Card Container */}
      <div
        style={{
          width: width * 0.82,
          height: width * 0.82, // Square card
          backgroundColor: cardColor,
          borderRadius: 30,
          border: `${width * 0.012}px solid #FFFFFF`,
          boxShadow: `${width * 0.02}px ${width * 0.02}px 0px #000000, 0 0 100px ${glowColor}`,
          transform: `scale(${cardScale}) rotate(-3deg)`, // Slight aggressive tilt
          opacity: cardOpacity,
          position: "relative",
          overflow: "hidden",
          display: "flex",
          flexDirection: "column",
          justifyContent: "center",
          padding: "8%",
        }}
      >
        {/* Thick Diagonal Zebra Stripes Background */}
        <svg
          style={{
            position: "absolute",
            top: 0,
            left: 0,
            width: "100%",
            height: "100%",
            opacity: 0.15,
            pointerEvents: "none",
          }}
        >
          <defs>
            <pattern
              id="stripes"
              width="60"
              height="60"
              patternUnits="userSpaceOnUse"
              patternTransform="rotate(45)"
            >
              <rect width="30" height="60" fill="#000000" />
            </pattern>
          </defs>
          <rect width="100%" height="100%" fill="url(#stripes)" />
        </svg>

        {/* List Items */}
        <div
          style={{
            display: "flex",
            flexDirection: "column",
            gap: "4%",
            height: "100%",
            justifyContent: "space-between",
            position: "relative",
            zIndex: 10,
          }}
        >
          {items.map((item, index) => {
            // Timing logic
            const itemAppearStart = 15 + index * 5;
            const itemAppear = spring({
              frame: frame - itemAppearStart,
              fps,
              config: { damping: 14, stiffness: 120 },
            });
            const itemY = interpolate(itemAppear, [0, 1], [50, 0]);
            
            // Base opacity starts lower, pops to 1 when active
            const itemInitialOpacity = interpolate(itemAppear, [0, 1], [0, 0.5]);

            const checkStartFrame = 45 + index * staggerFrames;
            const activeStartFrame = checkStartFrame - 15;

            // Is the item currently "active" (next in line) or already checked?
            const isActiveProgress = interpolate(
              frame,
              [activeStartFrame, activeStartFrame + 8],
              [0, 1],
              { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
            );

            const currentOpacity = itemInitialOpacity + isActiveProgress * 0.5;
            
            // Row scales up slightly when active for emphasis
            const rowScale = interpolate(isActiveProgress, [0, 1], [1, 1.05]);

            const checkProgress = spring({
              frame: frame - checkStartFrame,
              fps,
              config: { damping: 10, stiffness: 150 }, // Fast punchy check
            });

            // Box fill animation
            const boxFillProgress = interpolate(checkProgress, [0, 0.4], [0, 1], {
              extrapolateRight: "clamp",
            });

            // Checkmark draw animation
            const markDrawProgress = interpolate(checkProgress, [0.4, 1], [0, 1], {
              extrapolateLeft: "clamp",
              extrapolateRight: "clamp",
            });

            // Extreme Text Glow
            const glowIntensity = interpolate(isActiveProgress, [0, 1], [0, 1]);

            return (
              <div
                key={index}
                style={{
                  display: "flex",
                  alignItems: "center",
                  gap: "4%",
                  transform: `translateY(${itemY}px) scale(${rowScale})`,
                  opacity: currentOpacity,
                  transformOrigin: "left center",
                }}
              >
                {/* Checkbox (Skewed and Bold) */}
                <div
                  style={{
                    width: "10%",
                    aspectRatio: "1/1",
                    border: `${width * 0.006}px solid #000000`,
                    backgroundColor: "#FFFFFF",
                    position: "relative",
                    display: "flex",
                    justifyContent: "center",
                    alignItems: "center",
                    transform: "skewX(-8deg)", // Matches text skew
                    boxShadow: `${width * 0.006}px ${width * 0.006}px 0px #000000`,
                    overflow: "hidden", // keeps fill contained
                    flexShrink: 0,
                  }}
                >
                  {/* Neon Fill background that expands */}
                  <div
                    style={{
                      position: "absolute",
                      inset: 0,
                      backgroundColor: checkColor,
                      transform: `scale(${boxFillProgress})`,
                      transformOrigin: "center",
                    }}
                  />

                  {/* SVG Checkmark */}
                  {markDrawProgress > 0 && (
                    <svg
                      viewBox="0 0 100 100"
                      style={{
                        position: "absolute",
                        width: "120%", // Slightly oversized checkmark
                        height: "120%",
                        zIndex: 2,
                      }}
                    >
                      <path
                        d="M 25 55 L 45 75 L 85 20"
                        fill="none"
                        stroke="#000000"
                        strokeWidth="20"
                        strokeDasharray={200}
                        strokeDashoffset={interpolate(
                          markDrawProgress,
                          [0, 1],
                          [200, 0]
                        )}
                        strokeLinecap="square"
                        strokeLinejoin="miter"
                      />
                    </svg>
                  )}
                </div>

                {/* Text Container */}
                <div
                  style={{
                    flex: 1, // Take remaining width
                    color: accentColor,
                    fontSize: width * 0.055, // Scaled down slightly to fit more text
                    fontWeight: 900,
                    fontStyle: "italic",
                    textTransform: "uppercase",
                    letterSpacing: "-0.03em",
                    // Heavy stroke + hard shadow + glowing aura
                    WebkitTextStroke: `${width * 0.004}px #000000`,
                    textShadow: `
                      ${width * 0.008}px ${width * 0.008}px 0px #000000, 
                      0 0 ${40 * glowIntensity}px ${glowColor}
                    `,
                    transform: "skewX(-8deg)", // Aggressive slant
                    lineHeight: 1.1, // Added slight line height to handle wrapping gracefully
                    whiteSpace: "normal", // Allow wrapping instead of clipping
                    wordBreak: "break-word", // Ensures exceptionally long words wrap inside container
                    overflow: "visible", // Show text glow correctly
                    paddingTop: "1%",
                  }}
                >
                  {item}
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default ChecklistAnimation;